class DialogScriptTests(unittest.TestCase):
    """The dialog-side rules, observed by running the real script with the
    bundled Node runtime; the parse check itself lives in
    tests/test_config_tool_js.py."""

    def run_dialog(self):
        if not os.path.isfile(NODE):
            self.skipTest("no bundled node/node.exe on this machine")
        script = os.path.join(_product_root(), "input_methods",
                              "chewing", "js", "user_phrase.js")
        try:
            completed = subprocess.run(
                [NODE, "-e", DIALOG_HARNESS, script],
                cwd=ROOT,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                timeout=TIMEOUT_SECONDS,
            )
        except OSError as error:
            self.skipTest("bundled node.exe cannot run here: %s" % error)
        except subprocess.TimeoutExpired:
            self.fail("node harness on %s timed out after %ss" % (script, TIMEOUT_SECONDS))
        self.assertEqual(0, completed.returncode,
                         completed.stdout.decode("utf-8", "replace"))
        return json.loads(completed.stdout.decode("utf-8"))

    def test_typed_phrase_gets_the_library_answer_and_posts_it(self):
        derived, unknown, mismatch, no_payload = self.run_dialog()

        self.assertEqual({"phrase": TWO_CHAR_PHRASE}, derived["derive_requested"])
        self.assertEqual(TWO_CHAR_BOPOMOFO, derived["bopomofo_after_derive"])
        self.assertEqual({"add": [{"phrase": TWO_CHAR_PHRASE,
                                   "bopomofo": TWO_CHAR_BOPOMOFO}]}, derived["posted"])

    def test_unknown_phrase_keeps_the_manually_typed_value(self):
        _derived, unknown, _mismatch, _no_payload = self.run_dialog()

        self.assertEqual(TWO_CHAR_BOPOMOFO, unknown["bopomofo_after_derive"])
        self.assertEqual({"add": [{"phrase": TWO_CHAR_PHRASE,
                                   "bopomofo": TWO_CHAR_BOPOMOFO}]}, unknown["posted"])

    def test_wrong_syllable_count_keeps_the_manually_typed_value(self):
        _derived, _unknown, mismatch, _no_payload = self.run_dialog()

        self.assertEqual(TWO_CHAR_BOPOMOFO, mismatch["bopomofo_after_derive"])

    def test_missing_payload_keeps_the_manually_typed_value(self):
        _derived, _unknown, _mismatch, no_payload = self.run_dialog()

        self.assertEqual(TWO_CHAR_BOPOMOFO, no_payload["bopomofo_after_derive"])


